"use client";

/**
 * Switch: an on/off setting that takes effect at once.
 * Purpose: wraps Radix Switch. Generated by shadcn, then re-themed to Grove. Owner: design system.
 * Props: every Radix Switch prop (checked, onCheckedChange, disabled, id, name...).
 * Responsive: 48 x 28 px; put it in a Label so the whole row is the click target.
 * Accessibility: role switch; Space toggles; always has a visible label saying what it controls.
 * States: off, on, hover, focus, disabled.
 * Dependencies: radix Switch, cn. Tests: controls.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .switch).
 */
import { Switch as SwitchPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function Switch({ className, ...props }: ComponentProps<typeof SwitchPrimitive.Root>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "inline-flex h-(--size-switch-h) w-(--size-switch-w) shrink-0 items-center rounded-pill bg-line-input",
        "transition-colors duration-(--dur) ease-standard data-[state=checked]:bg-primary",
        "disabled:cursor-not-allowed disabled:bg-line-strong",
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className="pointer-events-none block size-5.5 translate-x-0.75 rounded-pill bg-surface shadow-card transition-transform duration-(--dur) ease-standard data-[state=checked]:translate-x-5.75"
      />
    </SwitchPrimitive.Root>
  );
}

export { Switch };
